def _check_base(base):
    if not isinstance(base, int) or isinstance(base, bool):
        raise ValueError("base must be an int in 2..36")
    if base < 2 or base > 36:
        raise ValueError("base must be in 2..36")


def to_base(number, base):
    _check_base(base)
    if not isinstance(number, int) or isinstance(number, bool):
        raise ValueError("number must be an int")
    if number == 0:
        return "0"
    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    negative = number < 0
    n = -number if negative else number
    out = []
    while n > 0:
        out.append(digits[n % base])
        n //= base
    if negative:
        out.append("-")
    return "".join(reversed(out))


def from_base(text, base):
    _check_base(base)
    if not isinstance(text, str):
        raise ValueError("text must be a str")
    if text == "":
        raise ValueError("empty string")
    s = text
    negative = False
    if s[0] == "-":
        negative = True
        s = s[1:]
    if s == "":
        raise ValueError("lone minus")
    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    value = 0
    for ch in s:
        lower = ch.lower()
        if lower not in digits:
            raise ValueError("invalid character: %r" % ch)
        d = digits.index(lower)
        if d >= base:
            raise ValueError("digit not valid for base")
        value = value * base + d
    if negative:
        value = -value
    return value
